        margin: 8px 0 0;
        font-size: 0.92rem;
        line-height: 1.45;
      }

      .helper {
        color: var(--muted);
      }

      .error {
        color: var(--danger);
      }

      .actions {
        margin-top: 24px;
      }

      button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        background: linear-gradient(180deg, #3b82f6, var(--primary));
        color: #fff;
        font: inherit;
        font-weight: 700;
        padding: 14px 22px;
        min-width: 180px;
        cursor: pointer;
        box-shadow: 0 16px 28px rgba(37, 99, 235, 0.24);
        transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
      }

      button:hover {
        background: linear-gradient(180deg, #3b82f6, var(--primary-hover));
        transform: translateY(-1px);
        box-shadow: 0 18px 32px rgba(37, 99, 235, 0.28);
      }

      button:focus {
        outline: none;
        box-shadow: 0 0 0 4px var(--ring), 0 16px 28px rgba(37, 99, 235, 0.24);
      }

      .status {
        margin: 18px 0 0;
        color: #0f766e;
        font-weight: 600;
        min-height: 1.5em;
