    <main class="page">
      <section class="card" aria-labelledby="support-title">
        <header class="card__header">
          <p class="eyebrow">Support</p>
          <h1 id="support-title">Contact our team</h1>
          <p class="subtitle">
            Send us a message and we’ll get back to you as soon as possible.
          </p>
        </header>

        <form id="contact-form" novalidate>
          <div class="form-field">
            <label for="full-name">Full name <span class="required">*</span></label>
            <input id="full-name" name="fullName" type="text" autocomplete="name" required placeholder="Jane Doe" />
            <p class="error" id="full-name-error" hidden>Full name is required.</p>
          </div>

          <div class="form-field">
            <label for="email">Email address <span class="required">*</span></label>
            <input id="email" name="email" type="email" autocomplete="email" required placeholder="jane@example.com" />
            <p class="error" id="email-error" hidden>Please enter a valid email address.</p>
          </div>

          <div class="form-field">
            <label for="phone">Phone number</label>
            <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567" />
            <p class="helper">Optional. Include country code if you’d like us to call you back.</p>
          </div>

          <div class="actions">
            <button type="submit">Send message</button>
            <p class="status" id="form-status" aria-live="polite"></p>
          </div>
        </form>
