          input: document.getElementById("full-name"),
          error: document.getElementById("full-name-error"),
          validate: (value) => value.trim().length > 0,
          message: "Full name is required.",
        },
        {
          input: document.getElementById("email"),
          error: document.getElementById("email-error"),
          validate: (value) => value.trim().length > 0 && value.includes("@") && value.includes("."),
          message: "Please enter a valid email address.",
        },
      ];

      function setFieldState(field, isValid) {
        field.input.setAttribute("aria-invalid", String(!isValid));
        field.error.hidden = isValid;
        field.error.textContent = field.message;
      }

      function validateForm() {
        let valid = true;

        fields.forEach((field) => {
          const isValid = field.validate(field.input.value);
          setFieldState(field, isValid);
          if (!isValid) valid = false;
        });

        return valid;
      }

      fields.forEach((field) => {
        field.input.addEventListener("input", () => {
          if (field.error.hidden === false) {
            const isValid = field.validate(field.input.value);
            setFieldState(field, isValid);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        if (!validateForm()) {
          return;
        }

        form.reset();
        fields.forEach((field) => setFieldState(field, true));
        status.textContent = "Thanks — your message has been sent.";
      });
    </script>
