 <!doctype html>
 <html lang="en">
   <head>
     <meta charset="utf-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1" />
     <title>Support Contact Form</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f3f6fb;
         --surface: rgba(255, 255, 255, 0.88);
         --surface-border: rgba(15, 23, 42, 0.08);
         --text: #0f172a;
         --muted: #64748b;
         --primary: #2563eb;
         --primary-hover: #1d4ed8;
         --danger: #dc2626;
         --ring: rgba(37, 99, 235, 0.18);
         --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top, rgba(37, 99, 235, 0.16), transparent 34%),
           linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
         min-height: 100vh;
       }

       .page {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 32px 16px;
       }

       .card {
         width: min(100%, 720px);
         background: var(--surface);
         border: 1px solid var(--surface-border);
         border-radius: 24px;
         box-shadow: var(--shadow);
         backdrop-filter: blur(18px);
         overflow: hidden;
       }

       .card__header {
         padding: 32px 32px 0;
       }

       .eyebrow {
         margin: 0 0 10px;
         font-size: 0.8rem;
         font-weight: 700;
         letter-spacing: 0.14em;
         text-transform: uppercase;
         color: var(--primary);
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 2.8rem);
         line-height: 1.05;
       }

       .subtitle {
         margin: 12px 0 0;
         max-width: 58ch;
         color: var(--muted);
         font-size: 1rem;
         line-height: 1.6;
       }

       form {
         padding: 28px 32px 32px;
       }

       .form-field {
         margin-top: 18px;
       }

       label {
         display: inline-block;
         font-weight: 600;
         margin-bottom: 8px;
       }

       .required {
         color: var(--danger);
       }

       input {
         width: 100%;
         border: 1px solid #cbd5e1;
         border-radius: 14px;
         padding: 14px 16px;
         font: inherit;
         color: var(--text);
         background: #fff;
         transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
       }

       input::placeholder {
         color: #94a3b8;
       }

       input:focus {
         outline: none;
         border-color: var(--primary);
         box-shadow: 0 0 0 4px var(--ring);
       }

       input[aria-invalid="true"] {
         border-color: var(--danger);
       }

       .helper,
       .error {
         margin: 8px 0 0;
         font-size: 0.92rem;
         line-height: 1.45;
       }

       .helper {
         color: var(--muted);
       }

       .error {
         color: var(--danger);
       }

       .actions {
         margin-top: 24px;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 999px;
         background: linear-gradient(180deg, #3b82f6, var(--primary));
         color: #fff;
         font: inherit;
         font-weight: 700;
         padding: 14px 22px;
         min-width: 180px;
         cursor: pointer;
         box-shadow: 0 16px 28px rgba(37, 99, 235, 0.24);
         transition: transform 160ms ease, box-shadow 160ms ease, background 160ms ease;
       }

       button:hover {
         background: linear-gradient(180deg, #3b82f6, var(--primary-hover));
         transform: translateY(-1px);
         box-shadow: 0 18px 32px rgba(37, 99, 235, 0.28);
       }

       button:focus {
         outline: none;
         box-shadow: 0 0 0 4px var(--ring), 0 16px 28px rgba(37, 99, 235, 0.24);
       }

       .status {
         margin: 18px 0 0;
         color: #0f766e;
         font-weight: 600;
         min-height: 1.5em;
       }

       @media (max-width: 640px) {
         .card__header,
         form {
           padding-left: 20px;
           padding-right: 20px;
         }

         .card__header {
           padding-top: 24px;
         }
       }
     </style>
   </head>
   <body>
     <main class="page">
       <section class="card" aria-labelledby="support-title">
         <header class="card__header">
           <p class="eyebrow">Support</p>
           <h1 id="support-title">Contact our team</h1>
           <p class="subtitle">
             Send us a message and we’ll get back to you as soon as possible.
           </p>
         </header>

         <form id="contact-form" novalidate>
           <div class="form-field">
             <label for="full-name">Full name <span class="required">*</span></label>
             <input id="full-name" name="fullName" type="text" autocomplete="name" required placeholder="Jane Doe" />
             <p class="error" id="full-name-error" hidden>Full name is required.</p>
           </div>

           <div class="form-field">
             <label for="email">Email address <span class="required">*</span></label>
             <input id="email" name="email" type="email" autocomplete="email" required placeholder="jane@example.com" />
             <p class="error" id="email-error" hidden>Please enter a valid email address.</p>
           </div>

           <div class="form-field">
             <label for="phone">Phone number</label>
             <input id="phone" name="phone" type="tel" autocomplete="tel" placeholder="(555) 123-4567" />
             <p class="helper">Optional. Include country code if you’d like us to call you back.</p>
           </div>

           <div class="actions">
             <button type="submit">Send message</button>
             <p class="status" id="form-status" aria-live="polite"></p>
           </div>
         </form>
       </section>
     </main>

     <script>
       const form = document.getElementById("contact-form");
       const status = document.getElementById("form-status");
       const fields = [
         {
           input: document.getElementById("full-name"),
           error: document.getElementById("full-name-error"),
           validate: (value) => value.trim().length > 0,
           message: "Full name is required.",
         },
         {
           input: document.getElementById("email"),
           error: document.getElementById("email-error"),
           validate: (value) => value.trim().length > 0 && value.includes("@") && value.includes("."),
           message: "Please enter a valid email address.",
         },
       ];

       function setFieldState(field, isValid) {
         field.input.setAttribute("aria-invalid", String(!isValid));
         field.error.hidden = isValid;
         field.error.textContent = field.message;
       }

       function validateForm() {
         let valid = true;

         fields.forEach((field) => {
           const isValid = field.validate(field.input.value);
           setFieldState(field, isValid);
           if (!isValid) valid = false;
         });

         return valid;
       }
')
